    repo: &Path,
    status: &RepoStatus,
    diffs: &[FileDiff],
) -> SecretScanResult {
    let changed_paths = changed_paths(status, diffs);
    if changed_paths.is_empty() {
        return SecretScanResult {
            findings: Vec::new(),
            status: SecretScanStatus {
                state: SecretScanState::NotRun,
                message: Some("Sin cambios que analizar.".into()),
                ..Default::default()
            },
