                    .join("bin")
                    .join(binary),
            );
        }
    }

    #[cfg(not(target_os = "windows"))]
    {
        if let Some(home) = env::var_os("HOME") {
            candidates.push(
                PathBuf::from(home.clone())
                    .join(".cargo")
