fn infer_version_from_release(release: &GithubRelease, asset: &GithubReleaseAsset) -> String {
    let version = release.tag_name.trim_start_matches('v').trim().to_string();
    if !version.is_empty() {
        return version;
    }
    let fallback = asset
        .name
        .trim_start_matches("gitleaks_")
        .split('_')
        .next()
        .unwrap_or("")
        .trim()
        .to_string();
    if fallback.is_empty() {
        "latest".to_string()
    } else {
        fallback
    }
}

